@* Displays a single task as a card with move buttons *@

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1 text-muted small">@Task.Assignee</p>
        <div class="d-flex justify-content-between align-items-center">
            <div>
                <span class="badge @PriorityClass">@Task.Priority</span>
                <span class="text-muted small ms-1">@Task.DueDate.ToString("MMM dd")</span>
            </div>
            <div>
                @if (ShowMoveLeft)
                {
                    <button class="btn btn-outline-secondary btn-sm me-1"
                            @onclick="() => OnMoveLeft.InvokeAsync(Task)"
                            disabled="@IsMoving">
                        &larr;
                    </button>
                }
                @if (ShowMoveRight)
                {
                    <button class="btn btn-outline-secondary btn-sm"
                            @onclick="() => OnMoveRight.InvokeAsync(Task)"
                            disabled="@IsMoving">
                        &rarr;
                    </button>
                }
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public bool IsMoving { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}

@page "/board"
@using sv_3c2e347bc4f34fa28de0b200bb8a2817.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Total="allTasks.Count"
                ToDo="todoTasks.Count"
                InProgress="inProgressTasks.Count"
                DoneCount="doneTasks.Count"
                Overdue="@allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do"
                      ColumnStatus="To Do"
                      Tasks="todoTasks"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      IsMoving="isMoving"
                      OnMoveRight="task => MoveTask(task, \"In Progress\")"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />

        <KanbanColumn ColumnName="In Progress"
                      ColumnStatus="In Progress"
                      Tasks="inProgressTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      IsMoving="isMoving"
                      OnMoveLeft="task => MoveTask(task, \"To Do\")"
                      OnMoveRight="task => MoveTask(task, \"Done\")"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />

        <KanbanColumn ColumnName="Done"
                      ColumnStatus="Done"
                      Tasks="doneTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      IsMoving="isMoving"
                      OnMoveLeft="task => MoveTask(task, \"In Progress\")"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private bool isMoving;
    private string? errorMessage;
    private string searchText = "";

    private List<TaskItem> filteredTasks => string.IsNullOrWhiteSpace(searchText)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> todoTasks => filteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => filteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => filteredTasks.Where(t => t.Status == "Done").ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        isMoving = true;

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            isMoving = false;
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
    }
}

