+@page "/board"
+@using sv_3c2e347bc4f34fa28de0b200bb8a2817.Components.Board
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h3 class="mb-3">Kanban Board</h3>
+
+@if (isLoading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger">
+        <strong>Error:</strong> @errorMessage
+        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
+    </div>
+}
+else
+{
+    <BoardStats Total="allTasks.Count"
+                ToDo="todoTasks.Count"
+                InProgress="inProgressTasks.Count"
+                DoneCount="doneTasks.Count"
+                Overdue="@allTasks.Count(t => t.DueDate < DateTime.Today)" />
+
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="searchText" @bind:event="oninput" />
+    </div>
+
+    <div class="row g-3">
+        <KanbanColumn ColumnName="To Do"
+                      ColumnStatus="To Do"
+                      Tasks="todoTasks"
+                      ShowMoveLeft="false"
+                      ShowMoveRight="true"
+                      IsMoving="isMoving"
+                      OnMoveRight="task => MoveTask(task, \"In Progress\")"
+                      OnTaskCreated="HandleTaskCreated"
+                      TaskService="TaskService" />
+
+        <KanbanColumn ColumnName="In Progress"
+                      ColumnStatus="In Progress"
+                      Tasks="inProgressTasks"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="true"
+                      IsMoving="isMoving"
+                      OnMoveLeft="task => MoveTask(task, \"To Do\")"
+                      OnMoveRight="task => MoveTask(task, \"Done\")"
+                      OnTaskCreated="HandleTaskCreated"
+                      TaskService="TaskService" />
+
+        <KanbanColumn ColumnName="Done"
+                      ColumnStatus="Done"
+                      Tasks="doneTasks"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="false"
+                      IsMoving="isMoving"
+                      OnMoveLeft="task => MoveTask(task, \"In Progress\")"
+                      OnTaskCreated="HandleTaskCreated"
+                      TaskService="TaskService" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private bool isLoading = true;
+    private bool isMoving;
+    private string? errorMessage;
+    private string searchText = "";
+
+    private List<TaskItem> filteredTasks => string.IsNullOrWhiteSpace(searchText)
+        ? allTasks
+        : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
+
+    private List<TaskItem> todoTasks => filteredTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> inProgressTasks => filteredTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> doneTasks => filteredTasks.Where(t => t.Status == "Done").ToList();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
